/**
 * Phase 1.5 demo data (contract v3), layered on the MVP seed. Everything is relative to
 * the adapter clock, so dates never go stale:
 *
 * - **Tel Aviv weekly football** (`s-tlv-weekly`, hosted by Dana): 13 regulars, 12 of them
 *   moved over from the WhatsApp group through the invite link, 6 "always in"; six past
 *   weeks played (results, published teams, confirmations, photos) — the latest ended ~20 h
 *   ago, so its peer-rating and confirmation windows are open — and the next four weeks
 *   generated by `planSeriesOccurrences` (auto-joins included).
 * - **London 5-a-side** (`s-lon-5s`, hosted by James): Dana is *invited* (she played with
 *   James in Hyde Park), and the next occurrence is still inside the regulars-only window.
 * - Glicko levels: Dana 3.4 in football with a weekly history, provisional basketball;
 *   Yossi 4.1; the regulars in between. Peer ratings Dana received.
 * - Media Vault: an open gallery on Lunchtime Futsal (uploads until end + 2 h), a locked one
 *   on last week's game, venue-public photos at Yarkon and Charles Clore, pending tags for Dana.
 * - Network: friends (Yossi, Noa), an incoming request (Maya), an outgoing one (Lior).
 */
import {
  DEFAULT_DOMAIN_CONFIG,
  type EpochMs,
  type GameId,
  type LocalDate,
  type MediaTag,
  type NotificationKind,
  type NotificationParams,
  type PeerRating,
  type RatingUpdate,
  type RosterMember,
  type SeriesOccurrence,
  type SkillRating,
  type SportId,
  type Stars,
  type UserId,
} from '@st/domain';

import {
  addDaysToLocalDate,
  approximateLocation,
  connectionPair,
  effectiveMediaVisibility,
  epochToZoned,
  glickoLevel,
  isoWeekdayOf,
  mediaExpiresAt,
  occurrenceKey,
  planSeriesOccurrences,
  ratingPeriodIndex,
  ratingPeriodKey,
  toIso,
  zonedTimeToEpoch,
} from './domain';
import { applyPhase15Effects, participantRow } from './effects15';
import { photoDataUri, type PhotoScene } from './photos';
import type { MockGame, MockMedia, MockSeries, MockState } from './state';

const DANA = 'u-dana';
const HOUR = 60 * 60 * 1000;
const DAY = 24 * HOUR;
const TZ_TLV = 'Asia/Jerusalem';
const TZ_LON = 'Europe/London';
const WEEKDAY_EN = ['', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];

/** The latest local date whose `time` slot starts at or before `limit`. */
function lastSlotOnOrBefore(limit: EpochMs, time: string, tz: string): LocalDate {
  let d = epochToZoned(limit, tz).date;
  if (zonedTimeToEpoch(d, time, tz) > limit) d = addDaysToLocalDate(d, -1);
  return d;
}

/** The first local date whose `time` slot starts after `limit`. */
function firstSlotAfter(limit: EpochMs, time: string, tz: string): LocalDate {
  let d = epochToZoned(limit, tz).date;
  if (zonedTimeToEpoch(d, time, tz) <= limit) d = addDaysToLocalDate(d, 1);
  return d;
}

function notify(state: MockState, id: string, userId: UserId, kind: string, params: NotificationParams, gameId: GameId | null, at: EpochMs) {
  state.notifications.push({ id, userId, kind: kind as NotificationKind, params, gameId, sanctionId: null, readAt: null, createdAt: toIso(at) });
}

function member(seriesId: string, userId: UserId, joinedVia: RosterMember['joinedVia'], joinedAt: EpochMs, alwaysIn: boolean, status: RosterMember['status'] = 'regular'): RosterMember {
  return { seriesId, userId, status, alwaysIn, joinedVia, consecutiveMisses: 0, leaveOfferedAt: null, joinedAt: toIso(joinedAt), leftAt: null };
}

export function seedPhase15(state: MockState, now: EpochMs, base: EpochMs): void {
  const ctx = { now, notify: () => undefined };

  // ------------------------------------------------------------------ Tel Aviv weekly series
  const lastDate = lastSlotOnOrBefore(now - 21.5 * HOUR, '20:00', TZ_TLV);
  const weekday = isoWeekdayOf(lastDate);
  const yarkon = state.venues.get('v-tlv-yarkon');
  if (!yarkon) return;
  const tlvCreated = now - 70 * DAY;
  const tlv: MockSeries = {
    id: 's-tlv-weekly',
    hostId: DANA,
    sport: 'football',
    title: `${WEEKDAY_EN[weekday]} Night Football`,
    notes: 'Bring a dark and a light shirt. Teams are split on the pitch, ten minutes before kick-off.',
    visibility: 'public',
    venueId: yarkon.id,
    location: yarkon.location,
    approxLocation: approximateLocation(yarkon.location),
    hideExactLocation: false,
    capacity: 14,
    minPlayers: 10,
    depositMinor: 0,
    currency: 'ILS',
    depositForfeitTo: 'pot',
    womenOnly: false,
    teamCount: 2,
    recurrence: 'weekly',
    weekday,
    startTime: '20:00',
    timeZone: TZ_TLV,
    durationMinutes: 90,
    anchorDate: addDaysToLocalDate(lastDate, -35),
    endDate: null,
    horizonWeeks: 4,
    rosterPriorityHours: 24,
    autoJoinReconfirmHours: 48,
    skippedDates: [],
    scheduleRevision: 0,
    status: 'active',
    inviteToken: 'tlv-weekly-football-regulars',
    inviteRotatedAt: null,
    createdAt: toIso(tlvCreated),
    updatedAt: toIso(tlvCreated),
  };
  state.series.set(tlv.id, tlv);

  const tlvPeople = Array.from({ length: 14 }, (_, i) => `u-tlv-${i}`);
  const regulars = tlvPeople.slice(0, 13);
  regulars.forEach((u, i) => {
    // The WhatsApp group moved over in two evenings; one player was added by the host later.
    const viaLink = i < 12;
    const joined = viaLink ? tlvCreated + 2 * HOUR + i * 3 * HOUR : now - 30 * DAY;
    state.roster.set(`${tlv.id}|${u}`, member(tlv.id, u, viaLink ? 'invite_link' : 'host', joined, i < 6));
    if (viaLink) state.inviteJoins.push({ kind: 'series', targetId: tlv.id, userId: u, at: toIso(joined) });
  });
  state.roster.set(`${tlv.id}|u-tlv-13`, member(tlv.id, 'u-tlv-13', 'played_with', now - 3 * DAY, false, 'invited'));

  // Six past weeks, all played and rated (the latest still inside the 48 h windows).
  const pastOccurrences: SeriesOccurrence[] = [];
  const scores: [number, number][] = [
    [5, 4],
    [3, 3],
    [6, 2],
    [2, 4],
    [4, 4],
    [5, 3],
  ];
  for (let k = 1; k <= 6; k++) {
    const date = addDaysToLocalDate(lastDate, -7 * (k - 1));
    const start = zonedTimeToEpoch(date, '20:00', TZ_TLV);
    const end = start + 90 * 60 * 1000;
    const gameId = `g-tlv-wk-${k}`;
    const occ: SeriesOccurrence = {
      seriesId: tlv.id,
      occurrenceKey: occurrenceKey(tlv.id, 0, date),
      slotDate: date,
      scheduleRevision: 0,
      gameId,
      startsAt: toIso(start),
      endsAt: toIso(end),
      opensAt: toIso(start - 28 * DAY),
      priorityUntil: toIso(start - 27 * DAY),
      reconfirmAt: toIso(start - 48 * HOUR),
      releaseAt: toIso(start - 24 * HOUR),
      status: 'scheduled',
      overridden: false,
    };
    pastOccurrences.push(occ);
    state.occurrences.set(occ.occurrenceKey, occ);
    const game: MockGame = {
      id: gameId,
      seriesId: tlv.id,
      hostId: DANA,
      sport: 'football',
      title: tlv.title,
      notes: tlv.notes,
      visibility: 'public',
      venueId: yarkon.id,
      location: yarkon.location,
      approxLocation: tlv.approxLocation,
      hideExactLocation: false,
      capacity: 14,
      minPlayers: 10,
      startsAt: occ.startsAt,
      endsAt: occ.endsAt,
      depositMinor: 0,
      currency: 'ILS',
      depositForfeitTo: 'pot',
      womenOnly: false,
      status: 'completed',
      teamCount: 2,
      inviteToken: `inv-${gameId}`,
      createdAt: occ.opensAt,
      qrSecret: `qr-secret-${gameId}`,
    };
    state.games.set(gameId, game);
    const players = [DANA, ...regulars.filter((_, i) => (i + k) % 13 < 10)];
    players.forEach((u, i) => {
      const p = participantRow(gameId, u, 'approved', toIso(start - 3 * DAY + i * HOUR));
      // One no-show three weeks ago; everyone else checked in by QR.
      const verified = !(k === 3 && i === 4);
      p.attendance = verified ? 'verified' : 'no_show_unverified';
      p.checkInMethod = verified ? (i === 0 ? 'host' : 'qr') : null;
      p.checkedInAt = verified ? toIso(start - 6 * 60 * 1000 + i * 20_000) : null;
      p.team = verified ? i % 2 : null;
      state.participants.set(`${gameId}|${u}`, p);
    });
    state.teamsPublishedAt.set(gameId, toIso(start - 15 * 60 * 1000));
    state.results.set(gameId, { gameId, teamScores: scores[k - 1] ?? [3, 2], submittedBy: DANA, submittedAt: toIso(end + 8 * 60 * 1000) });
    const confirmers = players.filter((u) => u !== DANA).slice(0, k === 1 ? 3 : 6);
    for (const [i, u] of confirmers.entries()) {
      if (k === 1 && u === 'u-tlv-0') continue; // Yossi has not confirmed last week's score yet (e2e).
      state.resultConfirmations.push({ gameId, userId: u, verdict: 'confirm', createdAt: toIso(end + (20 + i * 7) * 60 * 1000) });
    }
  }

  // The next four weeks, generated by the domain planner four hours ago (auto-joins included).
  const genAt = base - 4 * HOUR;
  const tlvRoster = [...state.roster.values()].filter((m) => m.seriesId === tlv.id);
  const tlvPlan = planSeriesOccurrences({ series: { ...tlv, inviteToken: tlv.inviteToken }, existing: pastOccurrences, roster: tlvRoster }, DEFAULT_DOMAIN_CONFIG, genAt);
  applyPhase15Effects(state, tlvPlan.effects, { ...ctx, now: genAt });
  const nextTlv = tlvPlan.occurrences[0];
  if (nextTlv) {
    for (const u of ['u-tlv-6', 'u-tlv-7', 'u-tlv-8']) {
      state.participants.set(`${nextTlv.gameId}|${u}`, participantRow(nextTlv.gameId, u, 'approved', toIso(genAt + HOUR)));
    }
  }

  // ------------------------------------------------------------------ London 5-a-side
  const westway = state.venues.get('v-lon-westway');
  if (westway) {
    const lonNext = firstSlotAfter(now + 40 * HOUR, '19:00', TZ_LON);
    const lonWeekday = isoWeekdayOf(lonNext);
    const start1 = zonedTimeToEpoch(lonNext, '19:00', TZ_LON);
    const lonCreated = now - 120 * DAY;
    const lon: MockSeries = {
      id: 's-lon-5s',
      hostId: 'u-lon-0',
      sport: 'football',
      title: `${WEEKDAY_EN[lonWeekday]} 5-a-side at Westway`,
      notes: 'Astro pitch 3. Moulded studs or trainers, no blades.',
      visibility: 'public',
      venueId: westway.id,
      location: westway.location,
      approxLocation: approximateLocation(westway.location),
      hideExactLocation: false,
      capacity: 10,
      minPlayers: 8,
      depositMinor: 0,
      currency: 'GBP',
      depositForfeitTo: 'pot',
      womenOnly: false,
      teamCount: 2,
      recurrence: 'weekly',
      weekday: lonWeekday,
      startTime: '19:00',
      timeZone: TZ_LON,
      durationMinutes: 60,
      anchorDate: addDaysToLocalDate(lonNext, -56),
      endDate: null,
      horizonWeeks: 4,
      rosterPriorityHours: 48,
      autoJoinReconfirmHours: 48,
      skippedDates: [],
      scheduleRevision: 0,
      status: 'active',
      inviteToken: 'lon-westway-5s-regulars',
      inviteRotatedAt: null,
      createdAt: toIso(lonCreated),
      updatedAt: toIso(lonCreated),
    };
    state.series.set(lon.id, lon);
    for (let i = 1; i <= 7; i++) {
      const viaLink = i <= 5;
      const joined = lonCreated + i * 5 * HOUR;
      state.roster.set(`${lon.id}|u-lon-${i}`, member(lon.id, `u-lon-${i}`, viaLink ? 'invite_link' : 'played_with', joined, i <= 3));
      if (viaLink) state.inviteJoins.push({ kind: 'series', targetId: lon.id, userId: `u-lon-${i}`, at: toIso(joined) });
    }
    state.roster.set(`${lon.id}|${DANA}`, member(lon.id, DANA, 'played_with', now - 20 * HOUR, false, 'invited'));
    const lonGen = start1 - 72 * HOUR;
    const lonPlan = planSeriesOccurrences({ series: lon, existing: [], roster: [...state.roster.values()].filter((m) => m.seriesId === lon.id) }, DEFAULT_DOMAIN_CONFIG, lonGen);
    applyPhase15Effects(state, lonPlan.effects, { ...ctx, now: lonGen });
    const first = lonPlan.occurrences[0];
    if (first) {
      for (const u of ['u-lon-4', 'u-lon-5']) state.participants.set(`${first.gameId}|${u}`, participantRow(first.gameId, u, 'approved', toIso(lonGen + 2 * HOUR)));
    }
    notify(state, 'n-demo-roster', DANA, 'roster_added', { seriesTitle: lon.title, via: 'played_with', invited: 1, seriesId: lon.id }, null, now - 20 * HOUR);
  }

  // ------------------------------------------------------------------ Glicko levels and history
  const idx = ratingPeriodIndex(now);
  const period = (weeksAgo: number) => ratingPeriodKey(idx - weeksAgo);
  const skill = (userId: UserId, sport: SportId, family: SkillRating['formatFamily'], r: number, rd: number, games: number, weeksAgo: number): SkillRating => ({
    userId,
    sport,
    formatFamily: family,
    r,
    rd,
    sigma: 0.06,
    games,
    provisional: games < 10 || rd >= 100,
    level: glickoLevel(r),
    lastPeriod: period(weeksAgo),
    updatedAt: toIso(now - weeksAgo * 7 * DAY),
  });
  const history = (userId: UserId, sport: SportId, family: SkillRating['formatFamily'], rs: number[], rds: number[]) => {
    for (let i = 1; i < rs.length; i++) {
      const weeksAgo = rs.length - i;
      const before = { r: rs[i - 1] as number, rd: rds[i - 1] as number, sigma: 0.06 };
      const after = { r: rs[i] as number, rd: rds[i] as number, sigma: 0.06 };
      const p = period(weeksAgo);
      state.ratingUpdates.push({ userId, sport, formatFamily: family, period: p, before, after, gamesAdded: 1, frozen: false, dedupeKey: `rating:${userId}:${sport}:${family}:${p}` } satisfies RatingUpdate);
    }
  };
  state.skillRatings.push(skill(DANA, 'football', 'small_sided', 1580, 78, 14, 1), skill(DANA, 'basketball', 'half_court', 1438, 192, 4, 3));
  history(DANA, 'football', 'small_sided', [1500, 1471, 1458, 1490, 1483, 1512, 1531, 1526, 1557, 1580], [350, 260, 205, 168, 140, 118, 104, 96, 86, 78]);
  history(DANA, 'basketball', 'half_court', [1500, 1462, 1479, 1438], [350, 268, 224, 192]);
  state.skillRatings.push(skill('u-tlv-0', 'football', 'small_sided', 1712, 66, 22, 1));
  history('u-tlv-0', 'football', 'small_sided', [1640, 1655, 1671, 1668, 1694, 1712], [92, 84, 78, 74, 70, 66]);
  regulars.slice(1).forEach((u, i) => {
    state.skillRatings.push(skill(u, 'football', 'small_sided', 1230 + ((i * 97) % 520), 88 + ((i * 13) % 70), 6 + ((i * 5) % 16), 1));
  });

  // Peer ratings Dana received (private summary on her level card).
  const raters = ['u-tlv-1', 'u-tlv-2', 'u-tlv-3', 'u-tlv-4', 'u-tlv-5', 'u-tlv-6'];
  const sheet: Record<string, Stars>[] = [
    { speed: 4, ball_control: 4, passing: 5, defence: 3, overall: 4 },
    { speed: 3, ball_control: 4, passing: 4, defence: 3, overall: 4 },
    { speed: 4, ball_control: 5, passing: 5, defence: 4, overall: 4 },
    { speed: 4, ball_control: 3, passing: 4, overall: 3 },
    { speed: 5, ball_control: 4, passing: 4, defence: 3, overall: 4 },
    { passing: 5, overall: 4 },
  ];
  raters.forEach((rater, i) => {
    const game = `g-tlv-wk-${2 + (i % 3)}`;
    const g = state.games.get(game);
    state.peerRatings.push({ gameId: game, sport: 'football', raterId: rater, rateeId: DANA, scores: sheet[i] ?? { overall: 4 }, createdAt: toIso(Date.parse(g?.endsAt ?? toIso(now)) + (3 + i) * HOUR) } satisfies PeerRating);
  });

  // ------------------------------------------------------------------ Media Vault
  const addMedia = (id: string, gameId: GameId, uploaderId: UserId, scene: PhotoScene, createdAt: EpochMs, opts: { publicOptIn?: boolean; tags?: [UserId, MediaTag['status']][] } = {}) => {
    const game = state.games.get(gameId);
    if (!game) return;
    const created = toIso(createdAt);
    const tags: MediaTag[] = (opts.tags ?? []).map(([userId, status]) => ({
      mediaId: id,
      userId,
      taggedBy: uploaderId,
      status,
      vetoPublic: status === 'declined',
      createdAt: created,
      decidedAt: status === 'requested' ? null : toIso(createdAt + 40 * 60 * 1000),
    }));
    const item: MockMedia = {
      id,
      gameId,
      venueId: game.venueId,
      uploaderId,
      kind: 'photo',
      status: 'published',
      visibility: 'participants',
      publicOptIn: opts.publicOptIn ?? false,
      mimeType: 'image/jpeg',
      sizeBytes: 2_400_000 + (id.length * 73_000),
      durationSeconds: null,
      storagePath: `media/${gameId}/${id}/photo.jpg`,
      createdAt: created,
      publishedAt: toIso(createdAt + 20_000),
      expiresAt: mediaExpiresAt(created),
      removedAt: null,
      url: photoDataUri(id, scene),
      thumbnailUrl: photoDataUri(id, scene),
    };
    item.visibility = effectiveMediaVisibility(item, tags);
    state.media.set(id, item);
    state.mediaTags.push(...tags);
  };
  const lunch = state.games.get('g-tlv-9');
  if (lunch) {
    const end = Date.parse(lunch.endsAt);
    addMedia('m-tlv9-1', lunch.id, 'u-tlv-1', 'duskPitch', end - 50 * 60 * 1000, { tags: [[DANA, 'requested']] });
    addMedia('m-tlv9-2', lunch.id, DANA, 'huddle', end - 5 * 60 * 1000, { tags: [['u-tlv-0', 'accepted'], ['u-tlv-1', 'requested']] });
    addMedia('m-tlv9-3', lunch.id, DANA, 'ballMacro', end - 30 * 60 * 1000, { publicOptIn: true, tags: [['u-tlv-0', 'accepted']] });
    addMedia('m-tlv9-4', lunch.id, 'u-tlv-2', 'floodlights', end - 40 * 60 * 1000);
    addMedia('m-tlv9-5', lunch.id, 'u-tlv-0', 'huddle', end - 12 * 60 * 1000, { publicOptIn: true, tags: [[DANA, 'accepted']] });
    addMedia('m-tlv9-6', lunch.id, 'u-tlv-3', 'ballMacro', end - 20 * 60 * 1000);
  }
  const wk = (k: number) => Date.parse(state.games.get(`g-tlv-wk-${k}`)?.endsAt ?? toIso(now));
  addMedia('m-wk1-1', 'g-tlv-wk-1', 'u-tlv-3', 'floodlights', wk(1) - 30 * 60 * 1000, { tags: [[DANA, 'requested']] });
  addMedia('m-wk1-2', 'g-tlv-wk-1', 'u-tlv-0', 'floodlights', wk(1) - 10 * 60 * 1000, { publicOptIn: true });
  addMedia('m-wk1-3', 'g-tlv-wk-1', 'u-tlv-5', 'huddle', wk(1) + 15 * 60 * 1000, { publicOptIn: true, tags: [['u-tlv-2', 'accepted']] });
  addMedia('m-wk1-4', 'g-tlv-wk-1', DANA, 'duskPitch', wk(1) - 60 * 60 * 1000);
  addMedia('m-wk2-1', 'g-tlv-wk-2', 'u-tlv-4', 'ballMacro', wk(2) - 20 * 60 * 1000, { publicOptIn: true });
  addMedia('m-wk2-2', 'g-tlv-wk-2', 'u-tlv-1', 'duskPitch', wk(2) - 45 * 60 * 1000, { publicOptIn: true });
  addMedia('m-wk4-1', 'g-tlv-wk-4', 'u-tlv-6', 'huddle', wk(4) - 5 * 60 * 1000, { publicOptIn: true });
  addMedia('m-wk6-1', 'g-tlv-wk-6', DANA, 'floodlights', wk(6) - 25 * 60 * 1000, { publicOptIn: true });
  notify(state, 'n-demo-tag-1', DANA, 'media_tag_request', { mediaId: 'm-tlv9-1' }, 'g-tlv-9', now - 25 * 60 * 1000);
  notify(state, 'n-demo-tag-2', DANA, 'media_tag_request', { mediaId: 'm-wk1-1' }, 'g-tlv-wk-1', wk(1) + 40 * 60 * 1000);
  notify(state, 'n-demo-rate-yossi', 'u-tlv-0', 'peer_rating_open', {}, 'g-tlv-wk-1', wk(1) + 30 * 60 * 1000);

  // ------------------------------------------------------------------ Network
  const friendship = (requester: UserId, other: UserId, accepted: boolean, requestedAt: EpochMs) => {
    const pair = connectionPair(requester, other);
    state.friendships.set(`${pair.userA}|${pair.userB}`, {
      ...pair,
      friendStatus: accepted ? 'accepted' : 'requested',
      friendRequestedBy: requester,
      friendRequestedAt: toIso(requestedAt),
      friendAcceptedAt: accepted ? toIso(requestedAt + 5 * HOUR) : null,
    });
  };
  friendship(DANA, 'u-tlv-0', true, now - 60 * DAY);
  friendship('u-tlv-1', DANA, true, now - 45 * DAY);
  friendship('u-tlv-3', DANA, false, now - 2 * HOUR);
  friendship(DANA, 'u-tlv-4', false, now - DAY);
  notify(state, 'n-demo-friend', DANA, 'friend_request', { userId: 'u-tlv-3' }, null, now - 2 * HOUR);
  state.networkPrivacy.set(DANA, { userId: DANA, upcomingGamesVisibleTo: 'friends', updatedAt: toIso(now - 60 * DAY) });
}

